UPDATE workflows SET entity_schema = $j${"case_number": {"type": "string", "required": true, "label": "Case", "question": "Which case? Send the case number, for example CS-26-08-00017.", "description": "The case number, for example CS-26-08-00017. Any format is accepted.", "read_by": {"lookup": {"table": "cases", "match_column": "case_number", "normalize": "identifier", "show": ["case_number", "title"]}}}, "assignee_name": {"type": "string", "required": true, "label": "Give it to", "question": "Who should the case go to? Send their name, or say me.", "description": "Who the case goes to. If the person says me or myself, use the person's own name.", "read_by": {"lookup": {"table": "users", "match_column": "name", "where": {"is_active": true}, "show": ["name"]}}}, "comment_text": {"type": "string", "required": false, "label": "Note", "question": "Any note for them?", "description": "An optional note for them.", "read_by": "typed"}}$j$::jsonb WHERE intent_key = 'case_pass_on';
UPDATE workflows SET entity_schema = $j${"case_number": {"type": "string", "required": true, "label": "Case", "question": "Which case? Send the case number, for example CS-26-08-00017.", "description": "The case number, for example CS-26-08-00017. Any format is accepted.", "read_by": {"lookup": {"table": "cases", "match_column": "case_number", "normalize": "identifier", "show": ["case_number", "title"]}}}, "comment_text": {"type": "string", "required": true, "label": "Update", "question": "What is the update? Type the note.", "description": "The note to add.", "read_by": "typed"}}$j$::jsonb WHERE intent_key = 'case_add_update';
UPDATE workflows SET entity_schema = $j${"case_number": {"type": "string", "required": true, "label": "Case", "question": "Which case? Send the case number, for example CS-26-08-00017.", "description": "The case number, for example CS-26-08-00017. Any format is accepted.", "read_by": {"lookup": {"table": "cases", "match_column": "case_number", "normalize": "identifier", "show": ["case_number", "title"]}}}, "comment_text": {"type": "string", "required": true, "label": "Closing note", "question": "What was done? Type the closing note. It is compulsory.", "description": "The closing note, so everyone knows what was done. Compulsory.", "read_by": "typed"}}$j$::jsonb WHERE intent_key = 'case_close_with_note';
UPDATE workflows SET entity_schema = $j${"title": {"type": "string", "required": true, "label": "Problem", "question": "What is the problem? Send a short title, for example “Lift stuck on 5th floor”.", "description": "Short summary of the complaint, e.g. \"Water leakage in Wing 2 basement\"", "read_by": "typed"}, "location": {"type": "string", "required": true, "label": "Where", "question": "Where is it? Wing, flat or common area.", "description": "Wing / flat / common area where the issue is", "read_by": "typed"}, "priority": {"type": "string", "required": true, "label": "Priority", "question": "How urgent is it?", "description": "One of urgent, high, medium, low. ONLY set this if the user explicitly states an urgency level or uses clearly urgent language (for example emergency, immediately dangerous, fire). Never infer priority from the topic of the complaint alone. If not stated, leave it unset and ask the user, or default to medium only after telling them you are defaulting it.", "enum": ["urgent", "high", "medium", "low"]}, "description": {"type": "string", "required": false, "label": "Details", "description": "Optional longer explanation of the issue"}}$j$::jsonb WHERE intent_key = 'file_a_complaint';
UPDATE workflows SET entity_schema = $j${"case_number": {"type": "string", "required": true, "label": "Case", "question": "Which case? Send the case number, for example CS-26-08-00017.", "description": "The case number, for example CS-26-08-00017. Any format is accepted.", "read_by": {"lookup": {"table": "cases", "match_column": "case_number", "normalize": "identifier", "show": ["case_number", "title"]}}}}$j$::jsonb, sql_template = $j$SELECT cc.case_number, cc.title, cc.status, cc.priority, cc.location, cc.due_date, u2.name AS assigned_name FROM cases cc LEFT JOIN users u2 ON u2.id = cc.assigned_to_id WHERE cc.org_id = $1 AND cc.case_number ILIKE $2 $j$ WHERE intent_key = 'check_case_status';
UPDATE workflows SET response_format = 'list' WHERE intent_key IN ('view_all_cases', 'check_case_status');
UPDATE workflows SET steps = $j$[{"op": "resolve_entity", "params": {"table": "users", "into": "assignee", "name_from": "$fields.assignee_name", "match_column": "name", "where": {"is_active": true}}}, {"op": "db.update_row", "params": {"table": "cases", "set": {"assigned_to_id": "$assignee.id"}, "where": {"id": "$case.id"}}}, {"op": "db.insert_row", "params": {"table": "case_activity", "values": {"case_id": "$case.id", "activity_type": "assignment", "actor_user_id": "$user.user_id", "payload": {"to_name": "$assignee.name", "to_user_id": "$assignee.id"}}}}]$j$::jsonb WHERE intent_key = 'case_assign';
SELECT intent_key, response_format, (SELECT string_agg(k || CASE WHEN v ? 'read_by' THEN ' (read by ' || CASE WHEN jsonb_typeof(v -> 'read_by') = 'string' THEN v ->> 'read_by' ELSE 'lookup' END || ')' WHEN v ? 'enum' THEN ' (fixed answers)' ELSE ' (assistant)' END, ', ' ORDER BY k) FROM jsonb_each(entity_schema) AS e(k, v) WHERE jsonb_typeof(v) = 'object' AND (v ->> 'computed') IS DISTINCT FROM 'true') AS how_answers_are_read FROM workflows WHERE intent_key IN ('file_a_complaint', 'case_pass_on', 'case_add_update', 'case_close_with_note', 'check_case_status', 'view_all_cases') ORDER BY intent_key;
